import json, sys
data = json.load(sys.stdin)
# Group by headword_norm
groups = {}
for e in data:
    n = e['headword_norm']
    if n not in groups:
        groups[n] = []
    groups[n].append(e)
for norm in sorted(groups.keys()):
    entries = groups[norm]
    print(f'=== {norm} ({len(entries)} entries) ===')
    for e in entries[:5]:  # limit to 5 per norm
        print(f'  id={e[\"entry_id\"]} hw={e[\"headword\"]} root={e.get(\"root\")} pos={e.get(\"pos\")} src={e[\"dict_source_type\"]} dict={e[\"dict_name_ar\"]}')
        defn = (e.get('definitions_text') or '')[:200]
        if defn: print(f'    def: {defn}')
        tr = e.get('translation_en')
        if tr: print(f'    en: {tr}')
    if len(entries) > 5:
        print(f'  ... and {len(entries)-5} more')
    print()
"
